// ---------- text-to-speech context ----------
// Lets any editable / label element know whether TTS is on, without
// threading a prop through every layer.
const TTSContext = createContext(false);

function speak(text) {
  try {
    if (!("speechSynthesis" in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.rate = 1;
    window.speechSynthesis.speak(u);
  } catch (e) {
    /* speech synthesis unavailable — fail silently */
  }
}

// ---------- tiny inline-editable primitive ----------
function Editable({ value, onChange, as: Tag = "span", className = "" }) {
  // Read-only: this used to be a click-to-edit contentEditable field.
  // Clicking still reads it aloud when Text to Speech is on (see Settings).
  const ttsOn = useContext(TTSContext);
  return (
    <Tag className={className} onClick={ttsOn ? () => speak(value) : undefined}>
      {value}
    </Tag>
  );
}

function Chip({ text }) {
  return <span className="chip">{text}</span>;
}

function AddInline() {
  // Read-only build: adding new tags/skills/highlights is disabled.
  return null;
}

