// Deterministic local placeholder image — no network required, so it always renders.
function ph(seed) {
  const s = String(seed);
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
  return PLACEHOLDER_IMAGES[h % PLACEHOLDER_IMAGES.length];
}

// A photo in the app — read-only display, upload disabled in this build.
function EditablePhoto({ src, className = "", alt = "" }) {
  if (!src) return null;
  return (
    <div className={`photo-edit ${className}`}>
      <img className="photo-edit__img" src={src} alt={alt} />
    </div>
  );
}

function ResumeUpload({ resume }) {
  if (!resume) return null;
  return (
    <div className="resume-card">
      <div className="resume-card__icon"><FileText size={18} /></div>
      <div className="resume-card__name">{resume.name}</div>
      <div className="resume-card__actions">
        <a className="resume-card__btn" href={resume.dataUrl} download={resume.name} aria-label={`Download ${resume.name}`}>
          <Download size={14} /> Download
        </a>
      </div>
    </div>
  );
}

function Toggle({ checked, onChange, label }) {
  return (
    <button
      className={`toggle ${checked ? "toggle--on" : ""}`}
      onClick={() => onChange(!checked)}
      role="switch"
      aria-checked={checked}
      aria-label={label}
    >
      <span className="toggle__thumb" />
    </button>
  );
}

