// ── Theme helper ────────────────────────────────────────────────────────────
function makeTheme(darkMode, highContrast) {
  const dm = darkMode;
  const hc = highContrast;
  return {
    appBg: dm ? "#0f172a" : "#f7f8fa",
    phoneBg: dm ? "#1a2332" : "#e8edf2",
    card: dm ? "#1e293b" : "#fff",
    cardAlt: dm ? "#0f172a" : "#fafafa",
    border: hc ? (dm ? "#64748b" : "#9ca3af") : (dm ? "#334155" : "#f0f0f0"),
    borderMid: hc ? (dm ? "#475569" : "#6b7280") : (dm ? "#1e293b" : "#f5f5f5"),
    text: hc ? (dm ? "#fff" : "#000") : (dm ? "#e2e8f0" : "#111827"),
    textMed: hc ? (dm ? "#e2e8f0" : "#111827") : (dm ? "#cbd5e1" : "#374151"),
    subtext: hc ? (dm ? "#cbd5e1" : "#374151") : (dm ? "#94a3b8" : "#6b7280"),
    subtextLight: hc ? (dm ? "#94a3b8" : "#6b7280") : (dm ? "#64748b" : "#9ca3af"),
    inputBg: dm ? "#0f172a" : "#f7f8fa",
    inputBorder: hc ? (dm ? "#64748b" : "#6b7280") : (dm ? "#475569" : "#e5e7eb"),
    navBg: dm ? "rgba(15,23,42,0.97)" : "rgba(255,255,255,0.97)",
    navBorder: dm ? "rgba(255,255,255,0.08)" : "rgba(0,0,0,0.06)",
    sheetBg: dm ? "#1e293b" : "#fff",
    handle: dm ? "#475569" : "#d1d5db",
    iconBg: dm ? "#0f3460" : "#f0fdf4",
    headerBg: dm ? "#1e293b" : "#fff",
    headerBorder: dm ? "#334155" : "#f0f0f0",
    mapRoad: dm ? "#2a3a52" : "#a8b8c8",
    mapRoadLight: dm ? "#243347" : "#b8c8d8",
    mapRoadMid: dm ? "#1e2d42" : "#c2ccd6",
    mapRoadFaint: dm ? "#1a2636" : "#d0d8e0",
    mapBuilding: dm ? "#253347" : "#d6dde6",
    mapBuildingBorder: dm ? "#1a2840" : "#c2ccd6",
  };
}

