// ── Map with clickable pins ─────────────────────────────────────────────────
function MapSVG({
  showPins, activePinIdx, onPinClick, darkMode, showLabels,
}) {
  const t = makeTheme(darkMode, false);
  return (
    <svg viewBox="0 0 100 100" className="w-full h-full" style={{ background: t.phoneBg }}>
      <g fill="none" strokeLinecap="round" strokeLinejoin="round">
        <rect x="28" y="30" width="22" height="26" rx="1" fill={t.mapBuilding} stroke={t.mapBuildingBorder} strokeWidth="0.5" />
        <path d="M0 62 Q30 58 50 70 Q70 82 100 76" stroke={t.mapRoad} strokeWidth="3.5" fill="none" />
        <path d="M0 65 Q30 61 50 73 Q70 85 100 79" stroke={t.mapRoadLight} strokeWidth="2" fill="none" />
        <path d="M0 20 Q15 22 28 30" stroke={t.mapRoadMid} strokeWidth="1.8" />
        <path d="M50 30 Q58 28 68 20 Q80 14 100 18" stroke={t.mapRoadMid} strokeWidth="1.8" />
        <path d="M50 56 Q56 60 65 58 Q80 54 100 58" stroke={t.mapRoadMid} strokeWidth="1.5" />
        <path d="M0 80 Q12 78 22 74 Q30 70 36 68" stroke={t.mapRoadMid} strokeWidth="1.5" />
        <path d="M78 0 Q76 18 72 30 Q68 42 68 58" stroke={t.mapRoadMid} strokeWidth="1.5" />
        <path d="M28 30 Q26 50 22 62" stroke={t.mapRoadMid} strokeWidth="1.2" />
        <path d="M50 30 Q50 44 50 56" stroke={t.mapRoadMid} strokeWidth="1.2" />
        <path d="M100 40 Q88 42 78 44 Q68 46 50 56" stroke={t.mapRoadMid} strokeWidth="1.2" />
        <path d="M0 45 Q14 44 28 44" stroke={t.mapRoadFaint} strokeWidth="0.8" />
        <path d="M50 10 Q50 20 50 30" stroke={t.mapRoadFaint} strokeWidth="0.8" />
        <path d="M28 56 Q28 62 22 68" stroke={t.mapRoadFaint} strokeWidth="0.8" />
        <path d="M78 58 Q78 70 80 82 Q82 92 78 100" stroke={t.mapRoadFaint} strokeWidth="0.8" />
      </g>

      {/* Map labels */}
      {showLabels && MAP_LABELS.map((label, i) => (
        <text
          key={i}
          x={label.x}
          y={label.y}
          fontSize="3.2"
          fontFamily="Outfit, sans-serif"
          fill={darkMode ? "#64748b" : "#8fa3b8"}
          textAnchor="middle"
          style={{ userSelect: "none", pointerEvents: "none" }}
        >
          {label.text}
        </text>
      ))}

      {showPins && PINS.map((pin, i) => {
        const isActive = activePinIdx === i;
        return (
          <g
            key={i}
            className="pin-drop"
            style={{ animationDelay: `${pin.delay}ms`, transformOrigin: `${pin.x}% ${pin.y}%`, cursor: "pointer" }}
            onClick={() => onPinClick(i)}
          >
            {isActive && (
              <circle
                cx={pin.x}
                cy={pin.y}
                r="5.5"
                fill="none"
                stroke={GREEN}
                strokeWidth="0.9"
                className="pulse-ring"
                style={{ transformOrigin: `${pin.x}% ${pin.y}%` }}
              />
            )}
            <circle
              cx={pin.x}
              cy={pin.y}
              r={isActive ? 4.2 : 3.6}
              fill={isActive ? GREEN : (darkMode ? "#1e293b" : "#fff")}
              stroke={isActive ? GREEN : (darkMode ? "#94a3b8" : "#1a1a2e")}
              strokeWidth={isActive ? 0.8 : 0.6}
            />
            <g transform={`translate(${pin.x - 2.1}, ${pin.y - 1.82}) scale(0.118)`}>
              <rect x="4" y="10" width="22" height="16" rx="3" fill="none" stroke={isActive ? "#fff" : (darkMode ? "#94a3b8" : "#1a1a2e")} strokeWidth="2.5" />
              <path d="M26 14 Q32 14 32 20 Q32 26 26 26" fill="none" stroke={isActive ? "#fff" : (darkMode ? "#94a3b8" : "#1a1a2e")} strokeWidth="2.5" />
              <path d="M10 7 Q10 3 13 3" fill="none" stroke={isActive ? "#fff" : (darkMode ? "#94a3b8" : "#1a1a2e")} strokeWidth="2" strokeLinecap="round" />
              <path d="M16 5 Q16 1 19 1" fill="none" stroke={isActive ? "#fff" : (darkMode ? "#94a3b8" : "#1a1a2e")} strokeWidth="2" strokeLinecap="round" />
              <line x1="8" y1="30" x2="22" y2="30" stroke={isActive ? "#fff" : (darkMode ? "#94a3b8" : "#1a1a2e")} strokeWidth="2.5" strokeLinecap="round" />
            </g>
          </g>
        );
      })}
    </svg>
  );
}

