// ── Photo Search Modal ──────────────────────────────────────────────────────
function PhotoSearchModal({ onClose, onSearch }) {
  const [stage, setStage] = useState("capture");

  useEffect(() => {
    const t1 = setTimeout(() => setStage("analyzing"), 1600);
    const t2 = setTimeout(() => setStage("found"), 3200);
    const t3 = setTimeout(() => { onSearch(); onClose(); }, 4600);
    return () => { clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); };
  }, []);

  const DETECTED = ["Cafe / Dessert", "Bingsu / Shaved Ice", "Korean Sweet"];

  return (
    <div className="absolute inset-0 z-50 flex flex-col" style={{ background: "#000" }}>
      {/* Header */}
      <div className="flex items-center justify-between px-5 pt-14 pb-3">
        <button onClick={onClose} className="text-white/70 hover:text-white transition-colors">
          <svg viewBox="0 0 24 24" className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
          </svg>
        </button>
        <p className="text-white font-semibold text-sm">Photo Search</p>
        <div className="w-6" />
      </div>

      {/* Viewfinder */}
      <div className="flex-1 relative mx-4 mb-4 rounded-3xl overflow-hidden" style={{ background: "#111" }}>
        {/* Simulated photo — cafe image */}
        <img
          src={CAFE_PHOTOS[0]}
          alt="viewfinder"
          className="w-full h-full object-cover opacity-80"
          style={{ filter: "brightness(0.7)" }}
        />

        {/* Corner brackets */}
        {[
          "top-4 left-4 border-t-2 border-l-2",
          "top-4 right-4 border-t-2 border-r-2",
          "bottom-4 left-4 border-b-2 border-l-2",
          "bottom-4 right-4 border-b-2 border-r-2",
        ].map((cls, i) => (
          <div key={i} className={`absolute ${cls} border-white/80 w-8 h-8 rounded-sm`} />
        ))}

        {/* Scan line */}
        {stage === "analyzing" && (
          <div
            className="absolute left-4 right-4 h-0.5 rounded-full"
            style={{
              background: `linear-gradient(to right, transparent, ${GREEN}, transparent)`,
              animation: "scan-line 1.2s ease-in-out infinite",
              top: "50%",
            }}
          />
        )}

        {/* Center crosshair */}
        {stage === "capture" && (
          <div className="absolute inset-0 flex items-center justify-center">
            <div className="w-16 h-16 rounded-full border-2 border-white/50 flex items-center justify-center">
              <div className="w-2 h-2 rounded-full bg-white/70" />
            </div>
          </div>
        )}

        {/* Analyzing label */}
        {stage === "analyzing" && (
          <div className="absolute bottom-5 left-0 right-0 flex justify-center">
            <div className="flex items-center gap-2 px-4 py-2 rounded-full" style={{ background: "rgba(0,0,0,0.65)" }}>
              <div className="w-2 h-2 rounded-full animate-ping" style={{ background: GREEN }} />
              <p className="text-white text-xs font-medium">Analyzing image…</p>
            </div>
          </div>
        )}

        {/* Found tags */}
        {stage === "found" && (
          <div className="absolute inset-0 flex flex-col items-center justify-end pb-6 gap-3">
            <div className="flex flex-wrap justify-center gap-2 px-4">
              {DETECTED.map(tag => (
                <span
                  key={tag}
                  className="px-3 py-1.5 rounded-full text-xs font-semibold text-white fade-in-up"
                  style={{ background: `${GREEN}cc`, backdropFilter: "blur(4px)" }}
                >
                  {tag}
                </span>
              ))}
            </div>
            <p className="text-white/80 text-xs">Searching nearby places…</p>
          </div>
        )}
      </div>

      {/* Bottom hint */}
      <div className="pb-10 flex flex-col items-center gap-1">
        <p className="text-white/50 text-xs">Point at food, places or signs</p>
      </div>

      <style>{`
        @keyframes scan-line {
          0% { top: 20%; }
          50% { top: 80%; }
          100% { top: 20%; }
        }
      `}</style>
    </div>
  );
}

// ── Listening Overlay ────────────────────────────────────────────────────────
function ListeningOverlay({ onClose, onDone }) {
  useEffect(() => {
    const t = setTimeout(() => { onDone(); }, 2400);
    return () => clearTimeout(t);
  }, []);

  return (
    <div className="absolute inset-0 z-50 flex flex-col items-center justify-center" style={{ background: "rgba(0,0,0,0.55)", backdropFilter: "blur(6px)" }}>
      <button onClick={onClose} className="absolute top-14 right-5 text-white/50 hover:text-white/80 transition-colors">
        <svg viewBox="0 0 24 24" className="w-6 h-6" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </button>
      <div className="relative flex items-center justify-center mb-6">
        {[1,2,3].map(i => (
          <span key={i} className="absolute rounded-full" style={{
            width: 48 + i * 32, height: 48 + i * 32,
            border: `2px solid ${GREEN}`,
            opacity: 0.25 / i,
            animation: `pulse-ring ${0.8 + i * 0.3}s ease-out infinite`,
            animationDelay: `${i * 0.15}s`,
          }} />
        ))}
        <div className="w-16 h-16 rounded-full flex items-center justify-center" style={{ background: GREEN, boxShadow: `0 0 32px ${GREEN}88` }}>
          <svg viewBox="0 0 24 24" width={28} height={28} fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/>
            <path d="M19 10v2a7 7 0 01-14 0v-2"/>
            <line x1="12" y1="19" x2="12" y2="23"/>
            <line x1="8" y1="23" x2="16" y2="23"/>
          </svg>
        </div>
      </div>
      <p className="text-white font-bold text-xl mb-1">Listening…</p>
      <p className="text-white/60 text-sm">Say what you&apos;re looking for</p>
      <div className="flex gap-1 mt-5">
        {[0,1,2,3,4].map(i => (
          <div key={i} className="w-1 rounded-full" style={{
            background: GREEN,
            height: 8 + Math.random() * 20,
            animation: `blink ${0.4 + i * 0.1}s ease-in-out infinite alternate`,
            animationDelay: `${i * 0.08}s`,
          }} />
        ))}
      </div>
    </div>
  );
}

// ── TTS banner ───────────────────────────────────────────────────────────────
function TtsBanner({ darkMode }) {
  const [visible, setVisible] = useState(true);
  useEffect(() => {
    const t = setTimeout(() => setVisible(false), 3500);
    return () => clearTimeout(t);
  }, []);
  if (!visible) return null;
  return (
    <div
      className="absolute top-36 left-4 right-4 z-30 flex items-center gap-2.5 px-4 py-2.5 rounded-2xl fade-in-up"
      style={{
        background: darkMode ? "#0f3460" : "#eff6ff",
        border: `1px solid ${BLUE}33`,
        boxShadow: "0 2px 12px rgba(37,99,235,0.12)",
      }}
    >
      <div className="w-7 h-7 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: BLUE }}>
        <svg viewBox="0 0 24 24" width={14} height={14} fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
          <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>
          <path d="M19.07 4.93a10 10 0 010 14.14M15.54 8.46a5 5 0 010 7.07"/>
        </svg>
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-xs font-semibold" style={{ color: BLUE }}>Reading results aloud</p>
        <p className="text-xs" style={{ color: darkMode ? "#94a3b8" : "#6b7280" }}>6 places found near you…</p>
      </div>
      <div className="flex gap-0.5 items-end">
        {[1,2,3,4].map(i => (
          <div key={i} className="w-0.5 rounded-full" style={{
            background: BLUE,
            height: 4 + i * 3,
            animation: `blink ${0.3 + i * 0.1}s ease-in-out infinite alternate`,
            animationDelay: `${i * 0.07}s`,
          }} />
        ))}
      </div>
    </div>
  );
}

// ── Popular places bottom sheet ─────────────────────────────────────────────
function PopularPlacesSheet({ largeText, darkMode, highContrast, onSearch }) {
  const t = makeTheme(darkMode, highContrast);
  return (
    <div
      className="absolute bottom-0 left-0 right-0 z-20 sheet-rise"
      style={{
        borderRadius: "24px 24px 0 0",
        background: t.sheetBg,
        boxShadow: "0 -4px 32px rgba(0,0,0,0.10)",
        height: "48%",
        fontSize: largeText ? "112%" : "100%",
      }}
    >
      <div className="flex justify-center pt-3 pb-2">
        <div className="w-10 h-1 rounded-full" style={{ background: t.handle }} />
      </div>
      <div className="px-5 pb-3 flex items-center justify-between">
        <div>
          <p className="text-xs font-semibold uppercase tracking-widest" style={{ color: GREEN }}>Near You</p>
          <h2 className="text-lg font-bold leading-tight" style={{ color: t.text }}>Popular Places</h2>
        </div>
        <button
          onClick={onSearch}
          className="text-xs font-semibold px-3 py-1.5 rounded-full"
          style={{ background: darkMode ? "#0f3460" : "#f0fdf4", color: GREEN }}
        >
          Search area
        </button>
      </div>
      <div className="overflow-y-auto hide-scrollbar px-4 pb-24 space-y-2.5" style={{ maxHeight: "calc(100% - 96px)" }}>
        {POPULAR.map((place, idx) => (
          <div
            key={idx}
            className="flex items-center gap-3 px-3.5 py-3 rounded-2xl fade-in-up"
            style={{
              background: t.cardAlt,
              border: `1px solid ${t.border}`,
              animationDelay: `${idx * 55}ms`,
              opacity: 0,
            }}
          >
            <div className="w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: t.iconBg }}>
              <CategoryIcon type={place.type} size={20} color={GREEN} />
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-1.5">
                <p className="font-semibold text-sm truncate" style={{ color: t.text }}>{place.name}</p>
                {place.verified && <VerifiedBadge size={14} />}
              </div>
              <div className="flex items-center gap-1.5 mt-0.5">
                <span className="text-xs" style={{ color: t.subtext }}>{place.category}</span>
                <span className="text-xs" style={{ color: t.subtextLight }}>·</span>
                <span className="text-xs" style={{ color: t.subtext }}>{place.distance}</span>
              </div>
            </div>
            <div className="flex flex-col items-end flex-shrink-0">
              <div className="flex items-center gap-0.5">
                <svg viewBox="0 0 12 12" width={11} height={11} fill="#f59e0b"><polygon points="6 1 7.5 4.5 11 4.9 8.5 7.3 9.2 11 6 9.3 2.8 11 3.5 7.3 1 4.9 4.5 4.5"/></svg>
                <span className="text-xs font-bold" style={{ color: t.textMed }}>{place.rating}</span>
              </div>
              <span className="text-xs mt-0.5" style={{ color: t.subtextLight }}>{place.reviews}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── NaverToggle ───────────────────────────────────────────────────────────────────
function NaverToggle({ on, onToggle }) {
  return (
    <button
      onClick={onToggle}
      className="relative flex-shrink-0 transition-all duration-300"
      style={{ width: 44, height: 26, borderRadius: 13, background: on ? GREEN : "#d1d5db" }}
    >
      <span
        className="absolute top-1 transition-all duration-300"
        style={{
          width: 18, height: 18, borderRadius: "50%", background: "#fff",
          boxShadow: "0 1px 4px rgba(0,0,0,0.2)", left: on ? 22 : 4,
        }}
      />
    </button>
  );
}

// ── Settings page ───────────────────────────────────────────────────────────
function SettingsPage({
  largeText, setLargeText,
  heyNaverEnabled, setHeyNaverEnabled,
  darkMode, setDarkMode,
  highContrast, setHighContrast,
  mapLabels, setMapLabels,
  voiceSearch, setVoiceSearch,
  soundEffects, setSoundEffects,
  ttsResults, setTtsResults,
  volume, setVolume,
}) {
  const [signedIn, setSignedIn] = useState(false);
  const [showSignIn, setShowSignIn] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const t = makeTheme(darkMode, highContrast);

  const handleSignIn = () => {
    if (email && password) { setSignedIn(true); setShowSignIn(false); }
  };

  const Section = ({ title, children }) => (
    <div className="mb-5">
      <p className="text-xs font-semibold uppercase tracking-widest px-1 mb-2" style={{ color: t.subtextLight }}>{title}</p>
      <div className="rounded-2xl overflow-hidden" style={{ border: `1px solid ${t.border}`, background: t.card }}>
        {children}
      </div>
    </div>
  );

  const Row = ({ icon, label, sublabel, right, last = false }) => (
    <div className="flex items-center gap-3 px-4 py-3.5" style={{ borderBottom: last ? "none" : `1px solid ${t.borderMid}` }}>
      <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: t.iconBg }}>
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium" style={{ color: t.text }}>{label}</p>
        {sublabel && <p className="text-xs mt-0.5" style={{ color: t.subtext }}>{sublabel}</p>}
      </div>
      {right}
    </div>
  );

  return (
    <div className="absolute inset-0 z-30 flex flex-col" style={{ background: t.appBg }}>
      <div className="px-5 pt-16 pb-4" style={{ background: t.headerBg, borderBottom: `1px solid ${t.headerBorder}` }}>
        <h1 className="text-2xl font-bold" style={{ color: t.text }}>Settings</h1>
      </div>

      <div className="flex-1 overflow-y-auto hide-scrollbar px-4 pt-4 pb-24">

        {/* Account */}
        <Section title="Account">
          {signedIn ? (
            <Row
              icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>}
              label="user@email.com"
              sublabel="Signed in"
              right={
                <button onClick={() => setSignedIn(false)} className="text-xs font-semibold px-3 py-1.5 rounded-full" style={{ background: "#fee2e2", color: "#dc2626" }}>
                  Sign out
                </button>
              }
              last
            />
          ) : (
            <>
              <Row
                icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>}
                label="Sign in"
                sublabel="Access your saved places and history"
                right={
                  <button onClick={() => setShowSignIn(v => !v)} className="text-xs font-semibold px-3 py-1.5 rounded-full text-white" style={{ background: GREEN }}>
                    {showSignIn ? "Cancel" : "Sign in"}
                  </button>
                }
                last={!showSignIn}
              />
              {showSignIn && (
                <div className="px-4 pb-4 pt-1 space-y-2.5">
                  <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                    className="w-full px-4 py-2.5 rounded-xl text-sm outline-none"
                    style={{ background: t.inputBg, border: `1px solid ${t.inputBorder}`, color: t.text }}
                  />
                  <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                    className="w-full px-4 py-2.5 rounded-xl text-sm outline-none"
                    style={{ background: t.inputBg, border: `1px solid ${t.inputBorder}`, color: t.text }}
                  />
                  <button
                    onClick={handleSignIn}
                    className="w-full py-2.5 rounded-xl text-sm font-semibold text-white transition-opacity"
                    style={{ background: GREEN, opacity: email && password ? 1 : 0.5 }}
                  >
                    Continue
                  </button>
                  <p className="text-center text-xs" style={{ color: t.subtext }}>
                    No account?{" "}
                    <span className="font-semibold" style={{ color: GREEN }}>Create one</span>
                  </p>
                </div>
              )}
            </>
          )}
        </Section>

        {/* Visual */}
        <Section title="Visual">
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>}
            label="Dark mode"
            sublabel={darkMode ? "Dark interface active" : "Switch to a darker interface"}
            right={<NaverToggle on={darkMode} onToggle={() => setDarkMode(!darkMode)} />}
          />
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 7h16M4 12h10M4 17h6"/></svg>}
            label="Large text"
            sublabel={largeText ? "Larger font size active" : "Increase font size throughout"}
            right={<NaverToggle on={largeText} onToggle={() => setLargeText(!largeText)} />}
          />
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>}
            label="High contrast"
            sublabel={highContrast ? "High contrast active" : "Improve readability"}
            right={<NaverToggle on={highContrast} onToggle={() => setHighContrast(!highContrast)} />}
          />
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M1 6l22 0M1 12h14M1 18h8"/></svg>}
            label="Map labels"
            sublabel={mapLabels ? "Street names visible on map" : "Show street and place names"}
            right={<NaverToggle on={mapLabels} onToggle={() => setMapLabels(!mapLabels)} />}
            last
          />
        </Section>

        {/* Audio */}
        <Section title="Audio">
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/><path d="M19 10v2a7 7 0 01-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/></svg>}
            label="Voice search"
            sublabel={voiceSearch ? "Mic button active in search bar" : "Enable microphone search"}
            right={<NaverToggle on={voiceSearch} onToggle={() => setVoiceSearch(!voiceSearch)} />}
          />
          <Row
            icon={
              <svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={heyNaverEnabled ? GREEN : "#9ca3af"} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <ellipse cx="12" cy="11" rx="4" ry="5"/><path d="M3 11c0 5 3.5 9 9 9s9-4 9-9"/><line x1="12" y1="20" x2="12" y2="23"/>
              </svg>
            }
            label='"Hey Naver" wake word'
            sublabel={heyNaverEnabled ? 'Always listening for "Hey Naver"' : "Tap to activate hands-free search"}
            right={<NaverToggle on={heyNaverEnabled} onToggle={() => setHeyNaverEnabled(!heyNaverEnabled)} />}
          />
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M19.07 4.93a10 10 0 010 14.14M15.54 8.46a5 5 0 010 7.07"/></svg>}
            label="Sound effects"
            sublabel={soundEffects ? "Playing sounds on interactions" : "Play sounds on interactions"}
            right={<NaverToggle on={soundEffects} onToggle={() => setSoundEffects(!soundEffects)} />}
          />
          <Row
            icon={<svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/></svg>}
            label="Read results aloud"
            sublabel={ttsResults ? "Results are spoken after search" : "Text-to-speech for search results"}
            right={<NaverToggle on={ttsResults} onToggle={() => setTtsResults(!ttsResults)} />}
          />
          {/* Volume slider */}
          <div className="px-4 py-3.5">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: t.iconBg }}>
                <svg viewBox="0 0 24 24" width={18} height={18} fill="none" stroke={GREEN} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                  <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/>
                  <line x1="15" y1="9" x2="19" y2="15"/>
                  <line x1="19" y1="9" x2="15" y2="15"/>
                </svg>
              </div>
              <div className="flex-1">
                <div className="flex justify-between mb-1.5">
                  <p className="text-sm font-medium" style={{ color: t.text }}>Volume</p>
                  <p className="text-sm font-semibold" style={{ color: GREEN }}>{volume}%</p>
                </div>
                <input
                  type="range"
                  min={0}
                  max={100}
                  value={volume}
                  onChange={e => setVolume(Number(e.target.value))}
                  className="w-full h-1.5 rounded-full appearance-none outline-none cursor-pointer"
                  style={{ accentColor: GREEN, background: `linear-gradient(to right, ${GREEN} ${volume}%, ${darkMode ? "#334155" : "#e5e7eb"} ${volume}%)` }}
                />
              </div>
            </div>
          </div>
        </Section>

        <div className="text-center mt-2 pb-2">
          <p className="text-xs" style={{ color: t.subtextLight }}>NavAI · Version 1.0.0</p>
        </div>
      </div>
    </div>
  );
}

// ── Bookmarks page ──────────────────────────────────────────────────────────
function BookmarksPage({ darkMode, highContrast, largeText }) {
  const t = makeTheme(darkMode, highContrast);
  return (
    <div className="absolute inset-0 z-30 flex flex-col" style={{ background: t.appBg, fontSize: largeText ? "112%" : "100%" }}>
      <div className="px-5 pt-16 pb-4" style={{ background: t.headerBg, borderBottom: `1px solid ${t.headerBorder}` }}>
        <h1 className="text-2xl font-bold" style={{ color: t.text }}>Bookmarks</h1>
        <p className="text-sm mt-0.5" style={{ color: t.subtext }}>{BOOKMARKS.length} saved places</p>
      </div>
      <div className="flex-1 overflow-y-auto hide-scrollbar px-4 pt-3 pb-24 space-y-2.5">
        {BOOKMARKS.map((place, idx) => (
          <div
            key={idx}
            className="rounded-2xl p-4 fade-in-up"
            style={{
              background: t.card,
              border: `1px solid ${t.border}`,
              animationDelay: `${idx * 55}ms`,
              opacity: 0,
            }}
          >
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: t.iconBg }}>
                <CategoryIcon type={place.type} size={22} color={GREEN} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-sm truncate" style={{ color: t.text }}>{place.name}</p>
                <p className="text-xs mt-0.5 truncate" style={{ color: t.subtext }}>{place.category}</p>
                <div className="flex items-center gap-2 mt-1">
                  <span className="text-xs font-medium" style={{ color: place.status === "Open" ? "#16a34a" : "#ef4444" }}>{place.status}</span>
                  <span style={{ color: t.subtextLight }}>·</span>
                  <span className="text-xs" style={{ color: t.subtext }}>{place.distance}</span>
                  <span style={{ color: t.subtextLight }}>·</span>
                  <span className="text-xs" style={{ color: t.subtext }}>★ {place.reviews}</span>
                </div>
              </div>
              <svg viewBox="0 0 24 24" className="w-4 h-4 flex-shrink-0" fill="none" stroke={t.subtextLight} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="9 18 15 12 9 6" />
              </svg>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── Main App ────────────────────────────────────────────────────────────────
function NaverPrototype() {
  const [phase, setPhase] = useState("idle");
  const [typedText, setTypedText] = useState("");
  const [showPins, setShowPins] = useState(true);
  const [sheetExpanded, setSheetExpanded] = useState(false);
  const [selectedPlace, setSelectedPlace] = useState(null);
  const [activePinIdx, setActivePinIdx] = useState(null);
  const [activeTab, setActiveTab] = useState("home");
  const [chatPinged, setChatPinged] = useState(false);

  // Accessibility state (lifted so they affect the whole app)
  const [largeText, setLargeText] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [highContrast, setHighContrast] = useState(false);
  const [mapLabels, setMapLabels] = useState(true);
  const [voiceSearch, setVoiceSearch] = useState(true);
  const [heyNaverEnabled, setHeyNaverEnabled] = useState(false);
  const [soundEffects, setSoundEffects] = useState(false);
  const [ttsResults, setTtsResults] = useState(false);
  const [volume, setVolume] = useState(70);

  // UI overlay states
  const [heyNaverListening, setHeyNaverListening] = useState(false);
  const [voiceListening, setVoiceListening] = useState(false);
  const [photoSearchOpen, setPhotoSearchOpen] = useState(false);
  const [showTtsBanner, setShowTtsBanner] = useState(false);

  const dragStartY = useRef(null);
  const sheetRef = useRef(null);

  const t = makeTheme(darkMode, highContrast);

  // Play a subtle click via Web Audio API
  const playClick = useCallback(() => {
    if (!soundEffects) return;
    try {
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0.08 * (volume / 100), ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
      osc.start();
      osc.stop(ctx.currentTime + 0.08);
    } catch { /* ignore */ }
  }, [soundEffects, volume]);

  // Speak results via Web Speech API
  const speakResults = useCallback((text) => {
    if (!ttsResults) return;
    try {
      window.speechSynthesis?.cancel();
      const u = new SpeechSynthesisUtterance(text);
      u.volume = volume / 100;
      u.rate = 1.05;
      window.speechSynthesis?.speak(u);
    } catch { /* ignore */ }
  }, [ttsResults, volume]);

  useEffect(() => {
    if (phase !== "typing") return;
    let idx = 0;
    const interval = setInterval(() => {
      setTypedText(QUERY.slice(0, idx + 1));
      idx++;
      if (idx >= QUERY.length) {
        clearInterval(interval);
        setTimeout(() => {
          setPhase("submitted");
          setShowPins(true);
          setTimeout(() => {
            setPhase("results-peek");
            playClick();
            if (ttsResults) {
              setShowTtsBanner(true);
              speakResults("Found 6 results for mango bingsu cafes near Gangnam. Top result: Mango Story Gangnam, 0.3 kilometres away, currently open.");
            }
          }, 700);
        }, 600);
      }
    }, 48);
    return () => clearInterval(interval);
  }, [phase, playClick, speakResults, ttsResults]);

  const handleSwipeUp = useCallback(() => {
    setSheetExpanded(true);
    setPhase("results-expanded");
  }, []);

  const dismissToMap = useCallback(() => {
    setSelectedPlace(null);
    setActivePinIdx(null);
    setSheetExpanded(false);
    setPhase("idle");
    setShowTtsBanner(false);
  }, []);

  const handleSwipeDown = useCallback(() => {
    if (selectedPlace !== null) {
      dismissToMap();
    } else if (sheetExpanded) {
      setSheetExpanded(false);
      setPhase("results-peek");
    } else {
      dismissToMap();
    }
  }, [selectedPlace, sheetExpanded, dismissToMap]);

  const handleTouchStart = (e) => { dragStartY.current = e.touches[0].clientY; };
  const handleTouchEnd = (e) => {
    if (dragStartY.current === null) return;
    const delta = e.changedTouches[0].clientY - dragStartY.current;
    if (delta < -40) handleSwipeUp();
    else if (delta > 60) handleSwipeDown();
    dragStartY.current = null;
  };
  const mouseStartY = useRef(null);
  const handleMouseDown = (e) => { mouseStartY.current = e.clientY; };
  const handleMouseUp = (e) => {
    if (mouseStartY.current === null) return;
    const delta = e.clientY - mouseStartY.current;
    if (delta < -40) handleSwipeUp();
    else if (delta > 60) handleSwipeDown();
    mouseStartY.current = null;
  };

  const handleSelectPlace = (idx) => {
    playClick();
    setSelectedPlace(idx);
    setActivePinIdx(PLACES[idx].pinIdx);
    setPhase("selected");
  };

  const handlePinClick = (pinIdx) => {
    const placeIdx = PLACES.findIndex(p => p.pinIdx === pinIdx);
    if (placeIdx === -1) return;
    playClick();
    setActivePinIdx(pinIdx);
    setSelectedPlace(placeIdx);
    setSheetExpanded(true);
    setActiveTab("home");
    setPhase("selected");
    setChatPinged(true);
  };

  const triggerHeyNaver = () => {
    if (phase !== "idle" && phase !== "typing") return;
    setHeyNaverListening(true);
    setTimeout(() => {
      setHeyNaverListening(false);
      if (phase === "idle") setPhase("typing");
    }, 2200);
  };

  const triggerVoiceSearch = () => {
    if (!voiceSearch) return;
    setVoiceListening(true);
  };

  const handleVoiceDone = () => {
    setVoiceListening(false);
    if (phase === "idle") setPhase("typing");
  };

  const handlePhotoSearch = () => {
    setPhotoSearchOpen(true);
  };

  const handlePhotoSearchDone = () => {
    if (phase === "idle") setPhase("typing");
  };

  const handleReset = () => {
    setPhase("idle");
    setTypedText("");
    setShowPins(false);
    setSheetExpanded(false);
    setSelectedPlace(null);
    setActivePinIdx(null);
    setActiveTab("home");
    setHeyNaverListening(false);
    setVoiceListening(false);
    setPhotoSearchOpen(false);
    setChatPinged(false);
    setShowTtsBanner(false);
    window.speechSynthesis?.cancel();
  };

  const showSheet = phase === "results-peek" || phase === "results-expanded" || phase === "selected";
  const isExpanded = sheetExpanded || phase === "selected" || phase === "results-expanded";
  const showPlaceholder = phase === "idle";

  const NAV_ITEMS = [
    { id: "home", icon: "home" },
    { id: "chat", icon: "chat" },
    { id: "bookmarks", icon: "star" },
    { id: "more", icon: "dots" },
  ];

  return (
    <div className="w-full flex items-center justify-center naver-proto" style={{ background: "linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)", padding: "26px 12px", borderRadius: 28 }}>
      <style>{`
        @keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }
        @keyframes fadeInUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
        .naver-proto .fade-in-up { animation: fadeInUp 0.4s ease forwards; }
        @keyframes pinDrop { 0% { opacity: 0; transform: scale(0) translateY(-8px); } 70% { transform: scale(1.15) translateY(2px); } 100% { opacity: 1; transform: scale(1) translateY(0); } }
        .naver-proto .pin-drop { animation: pinDrop 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
        @keyframes sheetRise { from { transform: translateY(100%); } to { transform: translateY(0); } }
        .naver-proto .sheet-rise { animation: sheetRise 0.45s cubic-bezier(0.32, 0.72, 0, 1) forwards; }
        @keyframes pulse-ring-kf { 0% { transform: scale(1); opacity: 0.6; } 100% { transform: scale(1.6); opacity: 0; } }
        .naver-proto .cursor-blink { animation: blink 1s step-end infinite; }
        @keyframes chat-glow { 0%, 100% { opacity: 0.25; transform: scale(1); } 50% { opacity: 0.55; transform: scale(1.12); } }
        .naver-proto .chat-glow { animation: chat-glow 1.2s ease-in-out infinite; }
        .naver-proto .hide-scrollbar::-webkit-scrollbar { display: none; }
        .naver-proto .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
      <div
        className="relative overflow-hidden shadow-2xl"
        style={{
          width: 300,
          height: 650,
          borderRadius: "40px",
          background: t.phoneBg,
          boxShadow: "0 40px 80px rgba(0,0,0,0.6), inset 0 0 0 1.5px rgba(255,255,255,0.15), 0 0 0 8px #0d1b2a",
        }}
      >
        {/* Status Bar */}
        <div className="absolute top-0 left-0 right-0 z-20 flex items-center justify-between px-6" style={{ paddingTop: "14px", paddingBottom: "4px" }}>
          <span className="text-xs font-semibold" style={{ color: t.textMed }}>9:41</span>
          <div className="flex gap-1 items-center">
            <svg viewBox="0 0 16 12" className="w-4 h-3" fill={t.textMed}><rect x="0" y="4" width="3" height="8" rx="0.5"/><rect x="4.5" y="2.5" width="3" height="9.5" rx="0.5"/><rect x="9" y="0.5" width="3" height="11.5" rx="0.5"/><rect x="13.5" y="0" width="2.5" height="12" rx="0.5" opacity="0.3"/></svg>
            <svg viewBox="0 0 16 12" className="w-4 h-3" fill={t.textMed}><path d="M8 2C5.5 2 3.3 3 1.7 4.7L0 3C2.1 1.1 4.9 0 8 0s5.9 1.1 8 3l-1.7 1.7C12.7 3 10.5 2 8 2z"/><path d="M8 6c-1.4 0-2.7.5-3.7 1.4L3 6C4.4 4.7 6.1 4 8 4s3.6.7 5 2l-1.3 1.4C10.7 6.5 9.4 6 8 6z"/><circle cx="8" cy="10" r="1.5"/></svg>
            <svg viewBox="0 0 25 12" className="w-6 h-3" fill="none" stroke={t.textMed} strokeWidth="1"><rect x="0.5" y="0.5" width="21" height="11" rx="2.5"/><path d="M22.5 4v4a2.5 2.5 0 000-4z"/><rect x="2" y="2" width="16" height="8" rx="1.5" fill={t.textMed}/></svg>
          </div>
        </div>

        {/* Page overlays */}
        {activeTab === "bookmarks" && <BookmarksPage darkMode={darkMode} highContrast={highContrast} largeText={largeText} />}
        {activeTab === "more" && (
          <SettingsPage
            largeText={largeText} setLargeText={setLargeText}
            heyNaverEnabled={heyNaverEnabled} setHeyNaverEnabled={setHeyNaverEnabled}
            darkMode={darkMode} setDarkMode={setDarkMode}
            highContrast={highContrast} setHighContrast={setHighContrast}
            mapLabels={mapLabels} setMapLabels={setMapLabels}
            voiceSearch={voiceSearch} setVoiceSearch={setVoiceSearch}
            soundEffects={soundEffects} setSoundEffects={setSoundEffects}
            ttsResults={ttsResults} setTtsResults={setTtsResults}
            volume={volume} setVolume={setVolume}
          />
        )}

        {/* Map */}
        <div className="absolute inset-0">
          <MapSVG showPins={showPins} activePinIdx={activePinIdx} onPinClick={handlePinClick} darkMode={darkMode} showLabels={mapLabels} />
        </div>

        {/* TTS Banner */}
        {showTtsBanner && ttsResults && <TtsBanner darkMode={darkMode} />}

        {/* Photo search modal */}
        {photoSearchOpen && (
          <PhotoSearchModal
            onClose={() => setPhotoSearchOpen(false)}
            onSearch={handlePhotoSearchDone}
          />
        )}

        {/* Voice listening overlay (mic button) */}
        {voiceListening && (
          <ListeningOverlay onClose={() => setVoiceListening(false)} onDone={handleVoiceDone} />
        )}

        {/* Hey Naver listening overlay */}
        {heyNaverListening && (
          <div className="absolute inset-0 z-50 flex flex-col items-center justify-center" style={{ background: "rgba(0,0,0,0.55)", backdropFilter: "blur(6px)" }}>
            <div className="relative flex items-center justify-center mb-6">
              {[1,2,3].map(i => (
                <span key={i} className="absolute rounded-full" style={{
                  width: 48 + i * 32, height: 48 + i * 32,
                  border: `2px solid ${GREEN}`,
                  opacity: 0.25 / i,
                  animation: `pulse-ring ${0.8 + i * 0.3}s ease-out infinite`,
                  animationDelay: `${i * 0.15}s`,
                }} />
              ))}
              <div className="w-16 h-16 rounded-full flex items-center justify-center" style={{ background: GREEN, boxShadow: `0 0 32px ${GREEN}88` }}>
                <svg viewBox="0 0 24 24" width={28} height={28} fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/>
                  <path d="M19 10v2a7 7 0 01-14 0v-2"/>
                  <line x1="12" y1="19" x2="12" y2="23"/>
                  <line x1="8" y1="23" x2="16" y2="23"/>
                </svg>
              </div>
            </div>
            <p className="text-white font-bold text-xl mb-1">Hey Naver</p>
            <p className="text-white/60 text-sm">Listening for your query…</p>
            <div className="flex gap-1 mt-5">
              {[0,1,2,3,4].map(i => (
                <div key={i} className="w-1 rounded-full" style={{
                  background: GREEN,
                  height: 8 + Math.random() * 20,
                  animation: `blink ${0.4 + i * 0.1}s ease-in-out infinite alternate`,
                  animationDelay: `${i * 0.08}s`,
                }} />
              ))}
            </div>
          </div>
        )}

        {/* Hey Naver floating button */}
        {heyNaverEnabled && activeTab === "home" && !heyNaverListening && (
          <button
            onClick={triggerHeyNaver}
            className="absolute z-20 flex items-center gap-2 px-3 py-2 rounded-full shadow-lg transition-transform active:scale-95"
            style={{
              bottom: 90, right: 16,
              background: t.card,
              border: `1.5px solid ${GREEN}`,
              boxShadow: `0 2px 12px ${GREEN}44`,
            }}
          >
            <div className="w-6 h-6 rounded-full flex items-center justify-center" style={{ background: GREEN }}>
              <svg viewBox="0 0 24 24" width={13} height={13} fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/>
                <path d="M19 10v2a7 7 0 01-14 0v-2"/>
              </svg>
            </div>
            <span className="text-xs font-semibold" style={{ color: GREEN }}>Hey Naver</span>
          </button>
        )}

        {/* Search Bar */}
        <div className="absolute top-12 left-0 right-0 z-10 px-4 pt-2" style={{ fontSize: largeText ? "112%" : "100%" }}>
          <div className="rounded-2xl px-4 py-3" style={{ background: t.card, boxShadow: darkMode ? "0 2px 16px rgba(0,0,0,0.4)" : "0 2px 16px rgba(0,0,0,0.12)" }}>
            <div className="flex items-start gap-3">
              <div
                className="w-8 h-8 rounded-full flex-shrink-0 flex items-center justify-center text-white text-sm font-bold mt-0.5"
                style={{ background: `linear-gradient(135deg, ${GREEN} 0%, #00a8e8 100%)` }}
              >
                N
              </div>
              <div className="flex-1 min-h-10">
                {showPlaceholder ? (
                  <div onClick={() => { playClick(); setPhase("typing"); }} className="cursor-text">
                    <p className="text-sm leading-snug" style={{ color: t.subtext }}>Tell me what you&apos;re looking for...</p>
                    <p className="text-xs mt-0.5" style={{ color: t.subtextLight }}>Ex: A mango bingsu cafe in Gangnam</p>
                  </div>
                ) : (
                  <div className="text-sm leading-snug font-medium" style={{ color: t.text }}>
                    {typedText}
                    {phase === "typing" && (
                      <span className="cursor-blink inline-block w-0.5 h-4 bg-blue-500 ml-0.5 align-middle" />
                    )}
                  </div>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between mt-2.5 pt-2" style={{ borderTop: `1px solid ${t.border}` }}>
              <div className="flex gap-3">
                {/* Camera / photo search */}
                <button
                  onClick={handlePhotoSearch}
                  className="transition-colors"
                  title="Photo search"
                  style={{ color: BLUE }}
                >
                  <svg viewBox="0 0 24 24" className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/>
                  </svg>
                </button>

                {/* Mic / voice search */}
                <button
                  onClick={triggerVoiceSearch}
                  disabled={!voiceSearch}
                  className="transition-colors"
                  title={voiceSearch ? "Voice search" : "Enable voice search in Settings"}
                  style={{ color: voiceSearch ? BLUE : t.subtextLight, opacity: voiceSearch ? 1 : 0.4 }}
                >
                  <svg viewBox="0 0 24 24" className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 1a3 3 0 00-3 3v8a3 3 0 006 0V4a3 3 0 00-3-3z"/><path d="M19 10v2a7 7 0 01-14 0v-2"/><line x1="12" y1="19" x2="12" y2="23"/><line x1="8" y1="23" x2="16" y2="23"/>
                  </svg>
                </button>
              </div>

              <button
                className="w-8 h-8 rounded-full flex items-center justify-center transition-all"
                style={{ background: phase === "idle" ? (darkMode ? "#334155" : "#d1d5db") : "#374151" }}
                onClick={() => { if (phase === "idle") { playClick(); setPhase("typing"); } }}
              >
                <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <line x1="12" y1="19" x2="12" y2="5"/><polyline points="5 12 12 5 19 12"/>
                </svg>
              </button>
            </div>
          </div>
        </div>

        {/* Popular places — shown on idle home */}
        {phase === "idle" && activeTab === "home" && (
          <PopularPlacesSheet
            largeText={largeText}
            darkMode={darkMode}
            highContrast={highContrast}
            onSearch={() => { playClick(); setPhase("typing"); }}
          />
        )}

        {/* Bottom Sheet */}
        {showSheet && activeTab === "home" && (
          <div
            ref={sheetRef}
            className="absolute bottom-0 left-0 right-0 z-20 sheet-rise"
            style={{
              borderRadius: "24px 24px 0 0",
              background: t.sheetBg,
              boxShadow: "0 -4px 32px rgba(0,0,0,0.12)",
              height: isExpanded ? "62%" : "22%",
              fontSize: largeText ? "112%" : "100%",
              transition: "height 0.45s cubic-bezier(0.32, 0.72, 0, 1)",
            }}
            onTouchStart={handleTouchStart}
            onTouchEnd={handleTouchEnd}
            onMouseDown={handleMouseDown}
            onMouseUp={handleMouseUp}
          >
            {/* Drag handle */}
            <div className="flex justify-center pt-3 pb-1">
              <div className="w-10 h-1 rounded-full" style={{ background: t.handle }} />
            </div>

            {/* Peek */}
            {!isExpanded && (
              <div className="px-5 pt-1">
                <p className="text-xs mb-0.5" style={{ color: t.subtext }}>15 verified results found</p>
                <div className="flex items-center gap-1.5">
                  <p className="text-xl font-bold" style={{ color: t.text }}>Dongmin Mokjang</p>
                  <VerifiedBadge size={18} />
                </div>
                <div className="mt-3 flex gap-2">
                  {PLACES[0].photos.slice(0, 4).map((url, i) => (
                    <div key={i} className="rounded-xl overflow-hidden bg-gray-100 flex-1" style={{ height: "56px" }}>
                      <img src={url} alt="cafe" className="w-full h-full object-cover" />
                    </div>
                  ))}
                </div>
                <button className="mt-3 w-full flex items-center justify-center gap-1 text-sm font-medium" style={{ color: BLUE }} onClick={handleSwipeUp}>
                  <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="18 15 12 9 6 15"/></svg>
                  See all results
                </button>
              </div>
            )}

            {/* Expanded list */}
            {isExpanded && selectedPlace === null && (
              <div className="flex flex-col h-full">
                <div className="px-5 pb-2">
                  <p className="text-xs" style={{ color: t.subtext }}>15 verified results found</p>
                </div>
                <div className="flex-1 overflow-y-auto hide-scrollbar px-4 pb-20 space-y-3">
                  {PLACES.map((place, idx) => (
                    <button
                      key={idx}
                      className="w-full text-left fade-in-up"
                      style={{ animationDelay: `${idx * 60}ms` }}
                      onClick={() => handleSelectPlace(idx)}
                    >
                      <div
                        className="rounded-2xl p-4 transition-all"
                        style={{
                          background: idx === selectedPlace ? (darkMode ? "#0f3460" : "#ebfdf3") : t.cardAlt,
                          border: idx === selectedPlace ? `1.5px solid ${GREEN}` : `1.5px solid ${t.border}`,
                        }}
                      >
                        <div className="flex items-start gap-3">
                          <div className="w-9 h-9 rounded-xl flex items-center justify-center flex-shrink-0 mt-0.5" style={{ background: t.iconBg }}>
                            <CategoryIcon type={place.type} size={18} color={GREEN} />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-1.5">
                              <p className="font-bold text-base truncate" style={{ color: t.text }}>{place.name}</p>
                              {place.verified && <VerifiedBadge size={15} />}
                            </div>
                            <p className="text-xs mt-0.5" style={{ color: t.subtext }}>
                              {place.category} &bull;{" "}
                              <span style={{ color: place.status === "Open" ? "#16a34a" : "#ef4444", fontWeight: 500 }}>
                                {place.status}
                              </span>{" "}
                              Opens at {place.opensAt} &bull; Reviews {place.reviews}
                            </p>
                            <p className="text-xs mt-0.5" style={{ color: t.subtextLight }}>{place.distance} &bull; {place.location}</p>
                          </div>
                          <svg viewBox="0 0 24 24" className="w-5 h-5 flex-shrink-0 mt-0.5" fill="none" stroke={t.subtextLight} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
                        </div>
                        {idx === 0 && (
                          <div className="mt-3 flex gap-2">
                            {place.photos.slice(0, 4).map((url, i) => (
                              <div key={i} className="flex-1 rounded-lg overflow-hidden bg-gray-100" style={{ height: "52px" }}>
                                <img src={url} alt={place.name} className="w-full h-full object-cover" />
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Selected detail */}
            {isExpanded && selectedPlace !== null && (() => {
              const place = PLACES[selectedPlace];
              return (
                <div key={selectedPlace} className="flex flex-col h-full overflow-y-auto hide-scrollbar fade-in-up">
                  <div className="px-5 pb-1 flex items-center justify-between flex-shrink-0">
                    <div className="flex items-center gap-2">
                      <button onClick={handleSwipeDown} style={{ color: t.subtext }}>
                        <svg viewBox="0 0 24 24" className="w-5 h-5" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
                      </button>
                      <p className="text-xs" style={{ color: t.subtext }}>Back</p>
                    </div>
                    <button
                      onClick={dismissToMap}
                      className="flex items-center gap-1 text-xs font-medium px-3 py-1.5 rounded-full transition-colors"
                      style={{ background: darkMode ? "#0f3460" : "#f0fdf4", color: GREEN }}
                    >
                      <svg viewBox="0 0 24 24" className="w-3.5 h-3.5" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
                      See map
                    </button>
                  </div>

                  <div className="px-5 pb-6">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h2 className="text-xl font-bold leading-tight" style={{ color: t.text }}>{place.name}</h2>
                      {place.verified && <VerifiedBadge size={18} />}
                    </div>
                    <p className="text-sm mt-1" style={{ color: t.subtext }}>
                      {place.category} &bull;{" "}
                      <span style={{ color: place.status === "Open" ? "#16a34a" : "#ef4444", fontWeight: 600 }}>
                        {place.status}
                      </span>
                      {" "}&bull; Opens {place.opensAt}
                    </p>

                    <div className="flex items-center gap-3 mt-2">
                      <div className="flex items-center gap-1">
                        {[1,2,3,4,5].map(s => (
                          <svg key={s} viewBox="0 0 12 12" width={13} height={13} fill={s <= 4 ? "#f59e0b" : (darkMode ? "#334155" : "#e5e7eb")}><polygon points="6 1 7.5 4.5 11 4.9 8.5 7.3 9.2 11 6 9.3 2.8 11 3.5 7.3 1 4.9 4.5 4.5"/></svg>
                        ))}
                        <span className="text-xs font-bold ml-0.5" style={{ color: t.textMed }}>4.8</span>
                      </div>
                      <span className="text-xs" style={{ color: t.subtext }}>({place.reviews} reviews)</span>
                      <span className="text-xs font-medium" style={{ color: GREEN }}>{place.distance}</span>
                    </div>

                    <div className="flex flex-wrap gap-1.5 mt-3">
                      {place.tags.map(tag => (
                        <span key={tag} className="px-2.5 py-1 rounded-full text-xs font-medium" style={{ background: darkMode ? "#0f3460" : "#f0fdf4", color: GREEN }}>
                          {tag}
                        </span>
                      ))}
                    </div>

                    <div className="flex gap-2 mt-4">
                      <button className="flex-1 py-2.5 rounded-full text-sm font-semibold" style={{ background: darkMode ? "#1e3a5f" : "#e0f2fe", color: "#0369a1" }}>
                        Directions
                      </button>
                      <button className="flex-1 py-2.5 rounded-full text-sm font-semibold text-white" style={{ background: BLUE }}>
                        Navigate
                      </button>
                      <button className="w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0" style={{ background: t.cardAlt, border: `1px solid ${t.border}` }}>
                        <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke={t.subtext} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>
                      </button>
                    </div>

                    {/* Photo grid */}
                    <div className="mt-4 grid grid-cols-2 gap-2">
                      <div className="col-span-1 row-span-2 rounded-2xl overflow-hidden bg-gray-100" style={{ height: 160 }}>
                        <img src={place.photos[0]} alt={place.name} className="w-full h-full object-cover" />
                      </div>
                      {place.photos.slice(1, 3).map((url, i) => (
                        <div key={i} className="rounded-xl overflow-hidden bg-gray-100" style={{ height: 76 }}>
                          <img src={url} alt={place.name} className="w-full h-full object-cover" />
                        </div>
                      ))}
                      {place.photos[3] && (
                        <div className="rounded-xl overflow-hidden bg-gray-100 relative" style={{ height: 76 }}>
                          <img src={place.photos[3]} alt={place.name} className="w-full h-full object-cover" />
                          <div className="absolute inset-0 flex items-center justify-center rounded-xl" style={{ background: "rgba(0,0,0,0.35)" }}>
                            <span className="text-white font-bold text-xs">+More</span>
                          </div>
                        </div>
                      )}
                    </div>

                    {/* Info card */}
                    <div className="mt-4 rounded-2xl overflow-hidden" style={{ border: `1px solid ${t.border}` }}>
                      {[
                        {
                          icon: <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>,
                          label: "Hours",
                          value: `${place.status} · Opens ${place.opensAt}`,
                          valueColor: place.status === "Open" ? "#16a34a" : "#ef4444",
                        },
                        {
                          icon: <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>,
                          label: "Address",
                          value: place.location,
                          valueColor: t.textMed,
                        },
                        {
                          icon: <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 16.92v3a2 2 0 01-2.18 2A19.86 19.86 0 013.09 5.18 2 2 0 015.06 3h3a2 2 0 012 1.72c.13.96.36 1.9.7 2.81a2 2 0 01-.45 2.11l-1.27 1.27a16 16 0 006.76 6.76l1.27-1.27a2 2 0 012.11-.45c.91.34 1.85.57 2.81.7A2 2 0 0122 16.92z"/></svg>,
                          label: "Phone",
                          value: place.phone,
                          valueColor: BLUE,
                        },
                        {
                          icon: <svg viewBox="0 0 24 24" className="w-4 h-4" fill="none" stroke={BLUE} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>,
                          label: "Reviews",
                          value: `${place.reviews} verified reviews`,
                          valueColor: t.textMed,
                        },
                      ].map(({ icon, label, value, valueColor }, i, arr) => (
                        <div key={label} className="flex gap-3 items-start px-4 py-3" style={{ borderBottom: i < arr.length - 1 ? `1px solid ${t.borderMid}` : "none", background: t.card }}>
                          <div className="w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5" style={{ background: darkMode ? "#1e3a5f" : "#eff6ff" }}>
                            {icon}
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-xs" style={{ color: t.subtext }}>{label}</p>
                            <p className="text-sm font-medium mt-0.5 truncate" style={{ color: valueColor }}>{value}</p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>
        )}

        {/* Bottom Nav */}
        <div
          className="absolute bottom-0 left-0 right-0 z-40 flex items-center justify-around px-2"
          style={{
            height: "72px",
            background: t.navBg,
            backdropFilter: "blur(12px)",
            borderTop: `1px solid ${t.navBorder}`,
            paddingBottom: "12px",
          }}
        >
          {NAV_ITEMS.map(({ id, icon }) => {
            const isActive = activeTab === id;
            const isPingedChat = id === "chat" && chatPinged;
            const color = isPingedChat ? GREEN : isActive && id === "bookmarks" ? GREEN : isActive ? BLUE : t.subtextLight;
            return (
              <button
                key={id}
                className="p-3 transition-transform active:scale-90 relative"
                onClick={() => { playClick(); setActiveTab(id); if (id === "chat") setChatPinged(false); }}
              >
                {isPingedChat && (
                  <span className="absolute inset-0 rounded-2xl chat-glow" style={{ background: `${GREEN}22` }} />
                )}
                <NavIcon icon={icon} color={color} />
                {id === "chat" && showSheet && (
                  <span
                    className="absolute top-2 right-2 flex items-center justify-center rounded-full text-white font-bold"
                    style={{
                      width: 16, height: 16, fontSize: 9,
                      background: chatPinged ? GREEN : "#6b7280",
                      boxShadow: `0 0 0 2px ${t.card}${chatPinged ? `, 0 0 8px ${GREEN}88` : ""}`,
                      transition: "background 0.3s, box-shadow 0.3s",
                    }}
                  >
                    15
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* Home indicator */}
        <div className="absolute bottom-2 left-0 right-0 z-50 flex justify-center pointer-events-none">
          <div className="w-28 h-1 rounded-full opacity-20" style={{ background: t.text }} />
        </div>

        {/* Reset */}
        {(phase === "selected" || phase === "results-expanded") && (
          <button
            className="absolute top-4 right-4 z-50 w-8 h-8 rounded-full flex items-center justify-center text-white text-xs font-bold"
            style={{ background: "rgba(0,0,0,0.35)", backdropFilter: "blur(4px)" }}
            onClick={handleReset}
            title="Restart demo"
          >
            ↺
          </button>
        )}
      </div>

      {/* Bottom hint */}
      <div className="absolute bottom-4 left-0 right-0 flex flex-col items-center">
        <p className="text-white/30 text-xs">Tap pins · Swipe sheet up · Tap ★ for bookmarks</p>
      </div>
    </div>
  );
}

// ==================== end Naver Maps prototype ====================

// ==================== Coupang redesign prototype (embedded case study demo) ====================

// Multicolor Coupang wordmark — exact brand letter colors
function CoupangLogo({ size = 26 }) {
  const letters = [
    { ch: "c", color: "#7B4913" },
    { ch: "o", color: "#7B4913" },
    { ch: "u", color: "#7B4913" },
    { ch: "p", color: "#E8391E" },
    { ch: "a", color: "#F5A800" },
    { ch: "n", color: "#6BAF2A" },
    { ch: "g", color: "#3AADE0" },
  ];
  return (
    <span aria-label="coupang" style={{ fontSize: size, fontWeight: 800, letterSpacing: "-0.5px", lineHeight: 1 }}>
      {letters.map(({ ch, color }) => (
        <span key={ch + color} style={{ color }}>{ch}</span>
      ))}
    </span>
  );
}

