function matchProducts(query) {
  const terms = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  if (!terms.length) return allProducts;

  const scored = allProducts.map(p => {
    const score = terms.reduce((s, term) => {
      if (p.name.toLowerCase().includes(term)) return s + 3;
      if (p.keywords.some(k => k.includes(term) || term.includes(k))) return s + 2;
      if (p.badge.toLowerCase().includes(term)) return s + 1;
      return s;
    }, 0);
    return { ...p, score };
  });

  const matched = scored.filter(p => p.score > 0).sort((a, b) => b.score - a.score);
  return matched.length > 0 ? matched : allProducts.slice(0, 6);
}

