function GeneralSearchResults({ query, onProductSelect }) {
  const [rocketOnly, setRocketOnly] = useState(false);

  const matched = matchProducts(query);
  const visible = rocketOnly ? matched.filter(p => p.rocketDelivery) : matched;
  const rocketCount = matched.filter(p => p.rocketDelivery).length;

  return (
    <div>
      {/* Toggle bar */}
      <div
        className="px-4 py-3 flex items-center gap-3 sticky top-0 z-10"
        style={{ background: "var(--card)", borderBottom: "1px solid var(--border)" }}
      >
        <p className="text-sm flex-1" style={{ color: "var(--muted-foreground)" }}>
          <strong style={{ color: "var(--foreground)" }}>{matched.length}</strong> results for "{query}"
        </p>
        <button
          onClick={() => setRocketOnly(r => !r)}
          className="flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-bold transition-all focus:outline-none focus:ring-2"
          style={{
            background: rocketOnly ? C.blue : "var(--secondary)",
            color: rocketOnly ? "#fff" : "var(--muted-foreground)",
            border: `1.5px solid ${rocketOnly ? C.blue : "var(--border)"}`,
          }}
          aria-pressed={rocketOnly}
          aria-label={`Filter by Rocket Delivery, ${rocketCount} items available`}
        >
          🚀 Rocket Delivery
          {rocketOnly && <span aria-hidden="true">✕</span>}
        </button>
      </div>

      {/* Rocket Delivery info strip — shown when toggled on */}
      {rocketOnly && (
        <div
          className="mx-4 mt-3 px-4 py-3 rounded-2xl flex items-center gap-3"
          style={{ background: `${C.blue}15`, border: `1px solid ${C.blue}40` }}
          role="status"
          aria-live="polite"
        >
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={C.blue} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
          </svg>
          <p className="text-xs font-semibold" style={{ color: C.blue }}>
            Order now · delivered <strong>tomorrow by 7 PM</strong>
          </p>
        </div>
      )}

      {/* Product grid */}
      <div className="px-4 pt-4 grid grid-cols-2 gap-3">
        {visible.map(p => (
          <article
            key={p.id}
            onClick={() => onProductSelect(p)}
            className="rounded-2xl overflow-hidden flex flex-col cursor-pointer active:scale-95 transition-transform"
            style={{
              background: "var(--card)",
              border: p.rocketDelivery
                ? `1.5px solid ${C.blue}40`
                : "1px solid var(--border)",
            }}
            aria-label={`${p.name}, ${p.price}`}
          >
            <div className="relative">
              <img
                src={p.img} alt={p.imgAlt}
                className="w-full aspect-square object-cover"
                style={{ background: "var(--secondary)" }}
              />
              {/* Delivery ribbon */}
              <div
                className="absolute bottom-0 left-0 right-0 px-2 py-1.5 flex items-center gap-1"
                style={{
                  background: p.rocketDelivery
                    ? `${C.blue}e8`
                    : "rgba(80,80,80,0.82)",
                }}
                aria-label={p.rocketDelivery ? `Rocket Delivery: ${p.deliveryLabel}` : `Standard delivery: ${p.deliveryLabel}`}
              >
                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                  <circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>
                </svg>
                <span className="text-xs font-semibold text-white truncate">{p.deliveryLabel}</span>
              </div>
            </div>

            <div className="p-3 flex flex-col gap-1 flex-1">
              {p.rocketDelivery && (
                <div className="mb-0.5"><RocketDeliveryBadge /></div>
              )}
              <span
                className="self-start text-xs font-semibold px-2 py-0.5 rounded-full"
                style={{ background: "var(--muted)", color: "var(--muted-foreground)" }}
              >
                {p.badge}
              </span>
              <p className="text-sm font-semibold leading-snug mt-1" style={{ color: "var(--foreground)" }}>{p.name}</p>
              <p className="text-xs" style={{ color: "var(--muted-foreground)" }} aria-label={`Rated ${p.rating} out of 5, ${p.reviews} reviews`}>
                ★ {p.rating} ({p.reviews.toLocaleString()})
              </p>
              <div className="mt-auto pt-2">
                <p className="text-base font-bold" style={{ color: "var(--foreground)" }}>{p.price}</p>
                <p className="text-xs" style={{ color: "var(--muted-foreground)" }}>
                  <s>{p.original}</s>
                  <span className="ml-1 font-semibold" style={{ color: p.rocketDelivery ? C.blue : C.red }}>{p.discount}</span>
                </p>
              </div>
              <button
                className="mt-2 w-full py-2 rounded-xl text-sm font-semibold hover:opacity-90 focus:outline-none focus:ring-2 transition-opacity"
                style={{ background: p.rocketDelivery ? C.blue : "var(--primary)", color: "#fff" }}
                aria-label={`Add ${p.name} to cart`}
              >
                Add to cart
              </button>
            </div>
          </article>
        ))}
      </div>

      {rocketOnly && visible.length === 0 && (
        <p className="px-4 pt-8 text-center text-sm" style={{ color: "var(--muted-foreground)" }}>
          No Rocket Delivery items found for this search.
        </p>
      )}
    </div>
  );
}

