function SearchPage({ freshFoodTrigger, onProductSelect }) {
  const [query, setQuery] = useState("");
  const [searched, setSearched] = useState(false);

  useEffect(() => {
    if (freshFoodTrigger > 0) {
      setQuery("Fresh Food");
      setSearched(true);
    }
  }, [freshFoodTrigger]);

  const handleSearch = (e) => {
    e.preventDefault();
    if (query.trim()) setSearched(true);
  };

  const isFreshFood = searched && query.toLowerCase().includes("fresh");

  return (
    <main className="flex-1 overflow-y-auto pb-24" aria-label="Search">
      {/* Search input */}
      <div className="px-4 pt-4 pb-3" style={{ borderBottom: "1px solid var(--border)" }}>
        <form onSubmit={handleSearch} role="search">
          <label htmlFor="search-main" className="sr-only">Search products</label>
          <div className="flex items-center gap-2 px-4 rounded-xl" style={{ background: "var(--secondary)", border: "1.5px solid var(--border)" }}>
            <IconSearch />
            <input
              id="search-main" type="search" value={query}
              onChange={e => { setQuery(e.target.value); setSearched(false); }}
              placeholder="What are you looking for?"
              className="flex-1 py-3 bg-transparent outline-none text-base"
              style={{ color: "var(--foreground)" }}
              autoFocus
            />
            {query && (
              <button type="submit" className="text-sm font-semibold px-2" style={{ color: "var(--primary)" }} aria-label="Search">Go</button>
            )}
          </div>
        </form>
      </div>

      {!searched ? (
        <div className="px-4 pt-5">
          <h2 className="text-xs font-semibold uppercase tracking-widest mb-3" style={{ color: "var(--muted-foreground)" }}>Popular searches</h2>
          <div className="flex flex-wrap gap-2">
            {searchSuggestions.map(s => (
              <button
                key={s}
                onClick={() => { setQuery(s); setSearched(true); }}
                className="px-4 py-2 rounded-full text-sm font-medium active:scale-95 transition-transform focus:outline-none focus:ring-2"
                style={{ background: "var(--secondary)", color: "var(--foreground)", border: "1px solid var(--border)" }}
                aria-label={`Search for ${s}`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      ) : isFreshFood ? (
        <div>
          {/* Rocket Fresh header banner */}
          <div className="px-4 py-4 flex items-center gap-3" style={{ background: T.green, borderBottom: `1px solid ${C.green}40` }}>
            <div className="flex-1">
              <div className="mb-1"><RocketFreshBadge /></div>
              <p className="text-sm font-semibold" style={{ color: "var(--foreground)" }}>Order by midnight —</p>
              <p className="text-base font-bold" style={{ color: C.green }}>delivered by 7 AM tomorrow</p>
            </div>
            <div className="text-4xl" aria-hidden="true">🥬</div>
          </div>

          <div className="px-4 pt-4">
            <p className="text-sm mb-4" style={{ color: "var(--muted-foreground)" }}>
              <strong style={{ color: "var(--foreground)" }}>{rocketFreshItems.length} items</strong> available for next-morning delivery
            </p>
            <div className="grid grid-cols-2 gap-3">
              {rocketFreshItems.map(item => <RocketFreshCard key={item.id} item={item} onSelect={onProductSelect} />)}
            </div>
          </div>
        </div>
      ) : (
        <GeneralSearchResults query={query} onProductSelect={onProductSelect} />
      )}
    </main>
  );
}

