function CartPage() {
  const [items, setItems] = useState(cartItems);

  const remove = (id) => setItems(prev => prev.filter(i => i.id !== id));
  const changeQty = (id, delta) =>
    setItems(prev => prev.map(i => i.id === id ? { ...i, qty: Math.max(1, i.qty + delta) } : i));

  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const shipping = 0;
  const total = subtotal + shipping;

  return (
    <main className="flex-1 overflow-y-auto pb-24">
      {items.length === 0 ? (
        <div className="flex flex-col items-center justify-center h-full gap-4 px-8 pt-24">
          <div style={{ color: "var(--muted-foreground)" }} aria-hidden="true"><IconCart /></div>
          <p className="text-lg font-semibold text-center">Your cart is empty</p>
          <p className="text-sm text-center" style={{ color: "var(--muted-foreground)" }}>Add items from the home page to get started.</p>
        </div>
      ) : (
        <>
          {/* Items */}
          <ul className="px-4 pt-5 flex flex-col gap-3" aria-label="Cart items" role="list">
            {items.map(item => (
              <li key={item.id} className="rounded-2xl overflow-hidden flex gap-3 p-3" style={{ background: "var(--card)", border: "1px solid var(--border)" }}>
                <img src={item.img} alt={item.imgAlt} className="w-20 h-20 rounded-xl object-cover flex-shrink-0" style={{ background: "var(--secondary)" }} />
                <div className="flex-1 flex flex-col gap-1">
                  <p className="text-sm font-semibold leading-snug">{item.name}</p>
                  {item.size !== "—" && <p className="text-xs" style={{ color: "var(--muted-foreground)" }}>Size: {item.size}</p>}
                  <p className="text-sm font-bold mt-auto">₩{(item.price * item.qty).toLocaleString()}</p>
                  {/* Qty + remove */}
                  <div className="flex items-center gap-2 mt-1">
                    <button
                      onClick={() => changeQty(item.id, -1)}
                      className="w-8 h-8 rounded-lg flex items-center justify-center font-bold text-lg focus:outline-none focus:ring-2"
                      style={{ background: "var(--secondary)", color: "var(--foreground)" }}
                      aria-label={`Decrease quantity of ${item.name}`}
                    >−</button>
                    <span className="text-sm font-semibold w-5 text-center" aria-label={`Quantity: ${item.qty}`}>{item.qty}</span>
                    <button
                      onClick={() => changeQty(item.id, 1)}
                      className="w-8 h-8 rounded-lg flex items-center justify-center font-bold text-lg focus:outline-none focus:ring-2"
                      style={{ background: "var(--secondary)", color: "var(--foreground)" }}
                      aria-label={`Increase quantity of ${item.name}`}
                    >+</button>
                    <button
                      onClick={() => remove(item.id)}
                      className="ml-auto p-2 rounded-lg focus:outline-none focus:ring-2"
                      style={{ color: "var(--muted-foreground)" }}
                      aria-label={`Remove ${item.name} from cart`}
                    ><IconTrash /></button>
                  </div>
                </div>
              </li>
            ))}
          </ul>

          {/* Order summary */}
          <section className="mx-4 mt-4 p-4 rounded-2xl" style={{ background: "var(--card)", border: "1px solid var(--border)" }} aria-label="Order summary">
            <h2 className="text-sm font-semibold mb-3">Order summary</h2>
            <div className="flex justify-between text-sm mb-2">
              <span style={{ color: "var(--muted-foreground)" }}>Subtotal</span>
              <span>₩{subtotal.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-sm mb-3">
              <span style={{ color: "var(--muted-foreground)" }}>Delivery</span>
              <span style={{ color: "#16a34a" }} aria-label="Free delivery">Free</span>
            </div>
            <div className="flex justify-between text-base font-bold" style={{ borderTop: "1px solid var(--border)", paddingTop: "12px" }}>
              <span>Total</span>
              <span>₩{total.toLocaleString()}</span>
            </div>
          </section>

          <div className="px-4 mt-4">
            <button
              className="w-full py-4 rounded-2xl text-base font-bold hover:opacity-90 focus:outline-none focus:ring-2 transition-opacity"
              style={{ background: "var(--primary)", color: "var(--primary-foreground)" }}
              aria-label={`Proceed to checkout, total ₩${total.toLocaleString()}`}
            >
              Checkout · ₩{total.toLocaleString()}
            </button>
          </div>
        </>
      )}
    </main>
  );
}

