function getSizes(p) {
  const keys = (p.keywords ?? []).concat((p.badge ?? "").toLowerCase());
  if (keys.some(k => ["shirt", "dress", "shorts", "fashion", "clothing"].includes(k))) return productSizes.clothing;
  if (keys.some(k => ["shoes", "sneakers", "running", "trainer"].includes(k))) return productSizes.shoes;
  return null;
}

