function CoupangPrototype() {
  const [activeNav, setActiveNav] = useState(0);
  const [searchValue, setSearchValue] = useState("");
  const [freshFoodTrigger, setFreshFoodTrigger] = useState(0);
  const [activeCategory, setActiveCategory] = useState(null);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const pageTitles = ["coupang", "Categories", "Search", "Account", "Cart"];

  const handleCategorySelect = (label) => setActiveCategory(label);
  const handleCategoryBack = () => setActiveCategory(null);

  return (
    <div className="coupang-proto" style={{ width: 336, height: 650, borderRadius: 40, overflow: "hidden", position: "relative", boxShadow: "0 30px 60px -20px rgba(20,21,26,0.35)", border: "8px solid #0d1b2a", margin: "0 auto" }}>
      <style>{`
        .coupang-proto {
          --background: #f8f8f7; --foreground: #111110; --card: #ffffff; --card-foreground: #111110;
          --primary: #E8391E; --primary-foreground: #ffffff; --secondary: #f0f0ef; --secondary-foreground: #111110;
          --muted: #e8e8e6; --muted-foreground: #6b6b6a; --accent: #E8391E; --accent-foreground: #ffffff;
          --border: #d4d4d2; --ring: #E8391E; --radius: 12px;
          font-family: 'Inter', system-ui, sans-serif;
        }
        .coupang-proto * { -webkit-tap-highlight-color: transparent; box-sizing: border-box; }
        .coupang-proto .cp-scroll::-webkit-scrollbar { display: none; }
        .coupang-proto .cp-scroll { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
      <div className="cp-scroll" style={{ position: "absolute", inset: 0, overflowY: "auto", background: "var(--background)", color: "var(--foreground)" }}>
      <div className="flex flex-col max-w-md mx-auto" style={{ minHeight: "100%", paddingBottom: 76, background: "var(--background)", color: "var(--foreground)" }}>

      {/* Header — hidden on Search page, category pages, and product detail */}
      {activeNav !== 2 && !activeCategory && !selectedProduct && (
        <header className="sticky top-0 z-30 flex items-center gap-3 px-4 py-3" style={{ background: "var(--card)", borderBottom: "1px solid var(--border)" }}>
          <div className="flex-1">
            {activeNav === 0
              ? <CoupangLogo size={26} />
              : <span className="text-xl font-bold" style={{ color: "var(--foreground)" }}>{pageTitles[activeNav]}</span>
            }
          </div>
          <button aria-label="Notifications, 8 unread" className="relative p-2 rounded-full" style={{ color: "var(--foreground)" }}>
            <IconBell />
            <span className="absolute top-1 right-1 w-4 h-4 text-xs font-bold flex items-center justify-center rounded-full" style={{ background: "var(--primary)", color: "var(--primary-foreground)" }} aria-hidden="true">8</span>
          </button>
        </header>
      )}

      {/* Search bar (Home only) */}
      {activeNav === 0 && !activeCategory && !selectedProduct && (
        <div className="px-4 py-3" style={{ background: "var(--card)", borderBottom: "1px solid var(--border)" }}>
          <label htmlFor="home-search" className="sr-only">Search products</label>
          <div className="flex items-center gap-2 px-4 rounded-xl" style={{ background: "var(--secondary)", border: "1.5px solid var(--border)" }}>
            <IconSearch />
            <input
              id="home-search" type="search" value={searchValue}
              onChange={e => setSearchValue(e.target.value)}
              onFocus={() => setActiveNav(2)}
              placeholder="Search products…"
              className="flex-1 py-3 bg-transparent outline-none text-base"
              style={{ color: "var(--foreground)" }}
              aria-label="Search products"
            />
            <button aria-label="Search by image" className="p-1" style={{ color: "var(--muted-foreground)" }}><IconCamera /></button>
          </div>
        </div>
      )}

      {/* Page content */}
      {selectedProduct
        ? <ProductDetailPage product={selectedProduct} onBack={() => setSelectedProduct(null)} onAddToCart={() => setSelectedProduct(null)} />
        : activeCategory
          ? <CategoryPage category={activeCategory} onBack={handleCategoryBack} onProductSelect={setSelectedProduct} />
          : <>
              {activeNav === 0 && <HomePage onSearch={() => setActiveNav(2)} onFreshFood={() => { setActiveNav(2); setFreshFoodTrigger(t => t + 1); }} onCategorySelect={handleCategorySelect} onProductSelect={setSelectedProduct} />}
              {activeNav === 1 && <CategoriesPage onCategorySelect={handleCategorySelect} />}
              {activeNav === 2 && <SearchPage freshFoodTrigger={freshFoodTrigger} onProductSelect={setSelectedProduct} />}
              {activeNav === 3 && <AccountPage />}
              {activeNav === 4 && <CartPage />}
            </>
      }
      </div>
      </div>

      {/* Bottom navigation */}
      <nav
        className="absolute bottom-0 left-0 w-full z-30"
        style={{ background: "var(--card)", borderTop: "1px solid var(--border)" }}
        aria-label="Main navigation"
      >
        <ul className="flex" role="list">
          {navItems.map((item, i) => {
            const isActive = activeNav === i;
            return (
              <li key={item.label} className="flex-1">
                <button
                  onClick={() => { setActiveNav(i); setActiveCategory(null); }}
                  className="relative flex flex-col items-center gap-1 w-full py-3 focus:outline-none focus:ring-2 focus:ring-inset transition-colors"
                  style={{ color: isActive ? "var(--primary)" : "var(--muted-foreground)" }}
                  aria-label={item.label}
                  aria-current={isActive ? "page" : undefined}
                >
                  <span className="relative" aria-hidden="true">
                    {item.icon}
                    {item.badge && (
                      <span className="absolute -top-1 -right-1 w-4 h-4 text-xs font-bold flex items-center justify-center rounded-full" style={{ background: "var(--primary)", color: "var(--primary-foreground)" }} aria-hidden="true">
                        {item.badge}
                      </span>
                    )}
                  </span>
                  <span className="text-xs font-medium">{item.label}</span>
                </button>
              </li>
            );
          })}
        </ul>
      </nav>
    </div>
  );
}

